/* ---------- answers -> the same JSON quiz-4 writes ---------- */
function snapshot(){
  const out={quiz_version:"v2"};const keys=[];
  for(const q of Q){if(q.key)keys.push(q.key);if(q.rows)q.rows.forEach(r=>keys.push(r.key))}
  for(const k of keys){const v=A[k];if(v===undefined||v==='__none')continue;out[k]=Array.isArray(v)?v.join(', '):v}
  ['dob','gender','height','weight','dietConsistency','additionalContext'].forEach(k=>{if(A[k])out[k]=A[k]});
  if(A.conditions==='__none')out.hasConditions='no';else if(Array.isArray(A.conditions)&&A.conditions.length)out.hasConditions='yes';
  if(A.medications==='__none')out.hasMedications='no';else if(Array.isArray(A.medications)&&A.medications.length)out.hasMedications='yes';
  return out;
}
// stored strings join options with ', ' and some options contain ', ': split by matching whole option labels
function splitStored(key,val){
  const s=String(val||'');if(!s)return undefined;const all=[];for(const q of Q){if(q.key===key&&q.opts)q.opts.forEach(o=>all.push(Array.isArray(o)?o[0]:o));if(q.rows)q.rows.forEach(r=>{if(r.key===key)r.opts.forEach(o=>all.push(o))})}
  const found=[];all.sort((a,b)=>b.length-a.length);let rest=', '+s+', ';
  for(const o of all){const t=', '+o+', ';if(rest.indexOf(t)>-1){found.push(o);rest=rest.replace(t,', ')}}
  return found.length?found.sort((a,b)=>s.indexOf(a)-s.indexOf(b)):undefined;
}

