let TVR=null;const LV=[["No signals","#2ce4ad"],["Worth checking","#f5b82e"],["Needs attention","#f3803d"],["Priority","#ef5a5a"]];
function loadResults(){return new Promise(res=>{if(window.TVResults&&window.TVResults.data){TVR=window.TVResults;res(TVR);return}
  const s=document.createElement('script');s.src=ASSET+'quiz-results-5.js';s.onload=()=>{TVR=window.TVResults||null;res(TVR)};s.onerror=()=>res(null);document.head.appendChild(s)})}
let live={lvl:{},why:{},read:new Set()};
function rawLevels(){if(!TVR)return null;const r=TVR.score(snapshot());const lvl={};for(const k in r.lvl)lvl[k]=r.base&&r.base[k]?0:r.lvl[k];return {lvl,why:r.why,r}}
function sysName(k){return TVR&&TVR.data.SYS[k]?TVR.data.SYS[k].n:k}
function listText(arr){const a=[...new Set(arr)];return a.length>1?a.slice(0,-1).join(', ')+' and '+a[a.length-1]:(a[0]||'')}
function update(changedId){
  if(changedId&&READS[changedId])READS[changedId].split(' ').filter(Boolean).forEach(k=>live.read.add(k));
  const x=rawLevels();if(!x){paintMeter();return}
  if(changedId==='symptoms'||changedId==='goals')for(const k in x.lvl)if(x.lvl[k]>0)live.read.add(k);
  const ups=[];for(const k in x.lvl){const was=live.lvl[k]||0;if(x.lvl[k]>was)ups.push([k,x.lvl[k]-was])}
  live.lvl=x.lvl;live.why=x.why;
  paintFigures(ups.map(u=>u[0]));
  if(ups.length){ups.sort((a,b)=>x.lvl[b[0]]-x.lvl[a[0]]||b[1]-a[1]);const k=ups[0][0];const w=[...new Set(x.why[k])].slice(-3);
    say('<b>'+esc(sysName(k))+'</b> <span style="color:'+LV[x.lvl[k]][1]+'">'+LV[x.lvl[k]][0].toLowerCase()+'</span><em>'+esc(cap1(listText(w)))+'</em>'+(ups.length>1?'<small>+'+(ups.length-1)+' more</small>':''))}
  paintMeter();paintFindings();
}
function cap1(s){return s?s.charAt(0).toUpperCase()+s.slice(1):s}
function say(html){document.querySelectorAll('.t5-say').forEach(el=>{el.innerHTML=html;el.classList.remove('in');void el.offsetWidth;el.classList.add('in')})}
function paintFigures(pulse){
  document.querySelectorAll('.t5-fig .organ').forEach(g=>{const k=g.getAttribute('data-sys');const l=live.lvl[k]||0;
    if(l>0){const c=LV[l][1];g.style.stroke=c;g.style.fill=c;g.style.color=c;g.style.fillOpacity=l>=2?'.62':'.42';g.style.strokeOpacity='1';g.classList.add('lit')}
    else{g.style.stroke='';g.style.fill='';g.style.color='';g.style.fillOpacity='';g.style.strokeOpacity='';g.classList.remove('lit')}
    if(pulse&&pulse.indexOf(k)>-1){g.classList.remove('pulse');void g.getBoundingClientRect();g.classList.add('pulse')}})
}
function paintMeter(){const n=live.read.size;document.querySelectorAll('.t5-meter').forEach(m=>{m.querySelector('b').textContent=n;m.querySelectorAll('i').forEach((d,i)=>d.classList.toggle('on',i<n))})}
function paintFindings(){
  const keys=Object.keys(live.lvl).filter(k=>live.lvl[k]>0).sort((a,b)=>live.lvl[b]-live.lvl[a]);
  document.querySelectorAll('.t5-finds').forEach(el=>{el.innerHTML=keys.length?keys.slice(0,6).map(k=>'<li><i style="background:'+LV[live.lvl[k]][1]+'"></i><div><b>'+esc(sysName(k))+'</b><span>'+esc(cap1(listText([...new Set(live.why[k])].slice(0,3))))+'</span></div></li>').join(''):'<li class="mt">Your answers light up the systems worth a closer look.</li>'});
}

