  const ultWhy=[];if(a.prio.length)ultWhy.push(cap1(listText(a.prio.slice(0,3).map(k=>S[k].n.toLowerCase())))+': the full picture, not a spot check');ultWhy.push((a.r.female?'139':'140')+' biomarkers across all 12 systems, read together');ultWhy.push('Ideal ranges set for your sex, age and answers');ultWhy.push('PhenoAge, TrueScore and a clinician-reviewed written report within 4 working days');
